<h1>User Account Management</h1><a class='btn' href='<?= url('users/create') ?>'>Add User</a><table><tr><th>ID</th><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Actions</th></tr><?php foreach($users as $u): ?><tr><td><?= e($u['user_id']) ?></td><td><?= e($u['full_name']) ?></td><td><?= e($u['email']) ?></td><td><?= e($u['role']) ?></td><td><?= $u['is_active']?'Active':'Inactive' ?></td><td><a href='<?= url('users/edit?id='.$u['user_id']) ?>'>Edit</a> | <a onclick="return confirm('Delete this user?')" href='<?= url('users/delete?id='.$u['user_id']) ?>'>Delete</a></td></tr><?php endforeach; ?></table>
